// Card photographs: real photographs from Wikimedia Commons.
// Derived from the 2026-11-08 Commons audit
// (~/workspace/planner-real-photos-audit/photos-audit.json, generated by
// generate-photos-module.py in the same directory; two entries were swapped
// after visual review, see SWAPS in that script) — the full audit, with
// Hybrid: the hotel’s own photo where Commons has one (36), a destination
// photo otherwise (62), a country-level photo for the last 2 (Maldives atoll
// for Vommuli; Serengeti landscape for Mereshi). All licenses are free at $0
// (CC BY / CC BY-SA variants, plus CC0); credit is shown on the card wherever
// attribution is required. Photos load from upload.wikimedia.org at view time
// — nothing is embedded in the bundle. If a file is renamed or deleted, the
// card falls back to the property’s brand illustration (see PropertyCard).

export type CardPhotoKind = 'hotel' | 'destination' | 'country';

export interface CardPhoto {
  /** 960px Wikimedia thumb URL, no tracking params. */
  src: string;
  /** 'hotel' = a photograph of the hotel; 'destination' / 'country' = a
      photograph of the area, never presented as the hotel itself. */
  kind: CardPhotoKind;
  /** Photographer / uploader name; null where no attribution is required (CC0). */
  artist: string | null;
  /** e.g. 'CC BY-SA 4.0'; null alongside a null artist. */
  license: string | null;
  /** Link to the license text, or null alongside a null artist. */
  licenseUrl: string | null;
}

